INSERT INTO par_tipos_visita (codigo, nombre, unidad, modalidad, aviso, periodicidad, finalidad, notificacion, fuente, orden) VALUES
  ('inicial', 'Programada inicial (línea base)', 'ESM', 'Dispensación', 'opl', 'Una vez, al 100 % de los ESM de dispensación en los 3 primeros meses del contrato.', 'Establecer el estado inicial de la operación, identificar brechas técnicas, administrativas y tecnológicas, verificar la adherencia a los lineamientos del contrato de medicamentos y construir la línea base para el modelo de riesgos del contrato.', 'Notificar a las DISANES y al OPL con mínimo 15 días de antelación: fecha, unidad de intervención, alcance específico y datos del equipo auditor (Anexo 3 p.9).', 'Anexo 3 p.12; p.9', 1),
  ('anual', 'Programada anual', 'ESM', 'Dispensación', 'opl', 'Cada año, de nuevo al 100 % de los ESM de dispensación.', 'Realizar nuevamente la auditoría de procesos in situ al 100 % de los ESM de dispensación.', 'Notificar a las DISANES y al OPL con mínimo 15 días de antelación: fecha, unidad de intervención, alcance específico y datos del equipo auditor (Anexo 3 p.9).', 'Anexo 3 p.12 (nota); p.9', 2),
  ('anexo', 'Programada según el anexo del contrato de medicamentos', 'ESM', 'Dispensación', 'opl', 'La que fije el anexo técnico del contrato de medicamentos. Ese documento no está disponible: sin dato.', 'Seguimiento y control al cumplimiento de las obligaciones del Operador Logístico en los ESM de modalidad dispensación.', 'Notificar a las DISANES y al OPL con mínimo 15 días de antelación: fecha, unidad de intervención, alcance específico y datos del equipo auditor (Anexo 3 p.9).', 'Anexo 3 p.12; p.9', 3),
  ('riesgo', 'Basada en riesgos', NULL, NULL, 'opl', 'Visitas periódicas. El Anexo 3 no fija la frecuencia.', 'Monitoreo específico de los riesgos estratificados a partir de las visitas iniciales y de los puntos críticos del proceso (PQRSR, trazabilidad de pendientes, facturación, planes de mejoramiento, entre otros), con la metodología de supervisión basada en riesgos de la Resolución 4559 de 2018. Se priorizan los establecimientos con mayor volumen de dispensación, hallazgos recurrentes, criticidad operativa o incidencias reportadas por DIGSA.', 'Notificar a las DISANES y al OPL con mínimo 15 días de antelación: fecha, unidad de intervención, alcance específico y datos del equipo auditor (Anexo 3 p.9).', 'Anexo 3 p.14; p.12; p.9', 4),
  ('necesidad', 'A necesidad de DIGSA, DISANES o JEFSA', NULL, NULL, 'no-opl', 'Cuando DIGSA, DISANES o JEFSA reporten novedades o incumplimiento de indicadores. Se realiza máximo 5 días hábiles después de notificada la solicitud.', 'Verificar las novedades o el incumplimiento de los indicadores del contrato de medicamentos reportados por DIGSA, DISANES o JEFSA.', 'Sin previo aviso al OPL y sin cronograma previo.', 'Anexo 3 p.14', 5),
  ('requerimiento', 'Por requerimiento (auditor de ciudad principal)', NULL, NULL, 'modulo', 'Cuando la operación, DIGSA o los hallazgos identificados lo exijan.', 'Verificar situaciones específicas, atender incidencias, validar información o realizar controles extraordinarios, bajo criterios de pertinencia, necesidad y riesgo.', 'Notificar a las DISANES, al OPL y al prestador con mínimo 3 días hábiles de antelación. El Anexo 3 no la regula: es un parámetro de la agenda.', 'Anexo 3 p.13-14 (num. 5)', 6),
  ('farmacia', 'A farmacia alterna del OPL', 'FA', NULL, 'opl', 'Anual, o con mayor frecuencia cuando la operación lo requiera.', 'Verificar la existencia y operación real del punto alterno, la disponibilidad y oportunidad en la entrega de medicamentos, la calidad del servicio prestado a los usuarios del SSFM y el cumplimiento de las condiciones técnicas, operativas y de infraestructura ofertadas por el operador.', 'Notificar a las DISANES y al OPL con mínimo 15 días de antelación: fecha, unidad de intervención, alcance específico y datos del equipo auditor (Anexo 3 p.9).', 'Anexo 3 p.12-13; p.9', 7),
  ('central', 'A nivel central del OPL', 'NC', NULL, 'opl', 'Anual.', 'Evaluar la gestión de inventarios, la trazabilidad, los mecanismos de control interno, la calidad del cargue de información, la interoperabilidad de las plataformas tecnológicas, el cumplimiento contractual y los procesos financieros y de facturación, verificando los procesos técnicos, jurídicos, tecnológicos y económicos centralizados.', 'Notificar a las DISANES y al OPL con mínimo 15 días de antelación: fecha, unidad de intervención, alcance específico y datos del equipo auditor (Anexo 3 p.9).', 'Anexo 3 p.13; p.9', 8),
  ('plan', 'Seguimiento a plan de mejoramiento', NULL, NULL, 'modulo', 'El Anexo 3 no fija periodicidad. El cumplimiento del plan se constata al vencimiento del plazo definido.', 'Verificar la implementación y el cumplimiento del plan de mejoramiento. Si se cumplió, se cierra; si no, o si fue ineficaz, se reporta a DIGSA y puede exigirse un nuevo plan.', 'Notificar a las DISANES, al OPL y al prestador con mínimo 3 días hábiles de antelación. El Anexo 3 no la regula: es un parámetro de la agenda.', 'Anexo 3 p.11-12', 9)
INSERT INTO par_parametros (clave, valor, descripcion, fuente, editable) VALUES
  ('notif_habiles_modulo', '3', 'Antelación mínima (días hábiles) de la notificación en visitas por requerimiento y de seguimiento a plan', 'Parámetro: el Anexo 3 no la regula', true),
  ('inicio_contrato', '', 'Fecha de inicio del contrato (plazo de la visita inicial)', 'Anexo 3 p.12', true),
  ('aviso_umbral_opl', '5', 'Días antes del límite de notificación al OPL desde los que la alerta pasa a advertencia', 'Definición interna DIGSA (sin respaldo en un anexo)', true),
  ('aviso_umbral_modulo', '1', 'Días antes del límite de notificación (requerimiento y plan) desde los que la alerta pasa a advertencia', 'Definición interna DIGSA (sin respaldo en un anexo)', true),
  ('notif_dias_opl', '15', 'Antelación mínima (días calendario) de la notificación a las DISANES y al OPL; si cae en día no hábil se corre al hábil anterior', 'Anexo 3 p.9', false),
  ('inicial_meses', '3', 'Meses para la visita inicial al 100 % de los ESM de dispensación', 'Anexo 3 p.12', false),
  ('max_seguimientos', '3', 'Máximo de visitas de seguimiento sobre un mismo plan 5W2H; después se escala al supervisor del contrato', 'Definición interna DIGSA (llamada 2026-10-14)', true),
  ('correo_digsa', '', 'Correo(s) de la DIGSA: reciben todas las actas, la notificación del nivel central y los escalamientos', 'Decisiones 9 y 24 (2026-10-15)', true),
  ('necesidad_habiles', '5', 'Días hábiles máximos entre la solicitud de una visita a necesidad y la visita', 'Anexo 3 p.14', false),
  ('recordatorio_seguimiento_habiles', '5', 'Días hábiles antes de la visita de seguimiento en que se recuerda al auditor por correo', 'Definición interna DIGSA (llamada 2026-10-14)', true),
  ('visitas_por_dia', '2', 'Propuesta de agenda: máximo de visitas por auditor en un mismo día', 'Decisión 32 (2026-10-15)', true),
  ('km_mismo_dia', '40', 'Propuesta de agenda: distancia máxima (km) entre los municipios visitados el mismo día por un auditor', 'Decisión 32 (2026-10-15)', true)
